WITH filtered_store_sales AS (SELECT * FROM store_sales WHERE units <= 35), agg AS (SELECT CASE WHEN units >= 32 THEN 'high' WHEN units >= 13 THEN 'mid' ELSE 'low' END AS units_bucket, product_id, AVG(units) AS avg_units FROM filtered_store_sales GROUP BY CASE WHEN units >= 32 THEN 'high' WHEN units >= 13 THEN 'mid' ELSE 'low' END, product_id) SELECT * FROM agg WHERE avg_units >= 38 ORDER BY 3 DESC;
